def handle_exception(self, exc: BaseException) -> BaseException | None:
    """
    Handle an exception based on the handler map.

    If the exception is a BaseExceptionGroup, split it and handle each part.
    Otherwise, find a matching handler for the exception type.

    Returns:
        - The original exception if no handler was found
        - None if the exception was fully handled
        - A new exception or exception group for partially handled cases
    """
    if isinstance(exc, BaseExceptionGroup):
        # Process exception group
        unhandled_exceptions = []

        for exc_types, handler in self._handler_map.items():
            # Split the group based on exception types
            matched, rest = exc.split(exc_types)

            if matched is not None:
                try:
                    handler(matched)
                except BaseException as handler_exc:
                    # If handler raises an exception, add it to unhandled
                    unhandled_exceptions.append(handler_exc)

                # Update the remaining exceptions
                exc = rest

                # If all exceptions were handled, return None
                if exc is None:
                    if unhandled_exceptions:
                        # If we have exceptions from handlers, create a new group
                        return BaseExceptionGroup("unhandled", unhandled_exceptions)
                    return None

        # If we have unhandled exceptions and exceptions from handlers
        if unhandled_exceptions and exc is not None:
            unhandled_exceptions.append(exc)
            return BaseExceptionGroup("unhandled", unhandled_exceptions)

        # Return any remaining unhandled exceptions
        return exc
    else:
        # Process single exception
        for exc_types, handler in self._handler_map.items():
            if isinstance(exc, exc_types):
                try:
                    handler(exc)
                    return None
                except BaseException as handler_exc:
                    return handler_exc

        # No handler found
        return exc

